    return <ol className='mx_FilteredDeviceList'>
        { sortedDevices.map((device) =>
            <li key={device.device_id}>
                <DeviceTile
                    device={device}
                />
            </li>,

        ) }
    </ol>;
};

export default FilteredDeviceList;

